// ---- Configuración: dónde está la API de vuelos ----
// n8n en Docker (Docker Desktop): host.docker.internal
// n8n en la misma red de Docker que la API: http://flight-tracker:8000
// n8n instalado directamente en el PC: http://localhost:8000
const API = 'http://host.docker.internal:8000';
const API_KEY = 'TU_API_KEY';

// ---- Parámetros de la URL: /webhook/vuelos?max_price=80&weekdays=4,5&destinations=LON,ROM ----
const q = $input.first().json.query || {};
const list = (s) => (s ? String(s).split(',').map((x) => x.trim()).filter(Boolean) : null);

const body = {
  origin: String(q.origin || 'AGP').toUpperCase(),
  max_price: Number(q.max_price || 100),
  min_nights: Number(q.min_nights || 2),
  max_nights: Number(q.max_nights || 3),
};

// weekdays: 0=lunes ... 6=domingo; "any" = cualquier día, cada step_days días
if (q.weekdays === 'any') {
  body.step_days = Number(q.step_days || 7);
} else {
  body.departure_weekdays = (list(q.weekdays) || ['4']).map(Number);
}
if (q.date_from) body.date_from = q.date_from;
if (q.date_to) body.date_to = q.date_to;
const dests = list(q.destinations);
if (dests) body.destinations = dests.map((d) => d.toUpperCase());
if (q.max_stops !== undefined && q.max_stops !== '') body.max_stops = Number(q.max_stops);

// Query para las ofertas precalculadas (/api/deals/latest)
const lq = { max_price: body.max_price, min_nights: body.min_nights, max_nights: body.max_nights,
             origin: body.origin, limit: 200 };
if (body.departure_weekdays) lq.weekdays = body.departure_weekdays.join(',');
if (body.date_from) lq.date_from = body.date_from;
if (body.date_to) lq.date_to = body.date_to;
if (body.destinations) lq.destinations = body.destinations.join(',');
if (body.max_stops !== undefined) lq.max_stops = body.max_stops;
if (q.sort === 'total') lq.sort = 'total';
if (q.max_total) lq.max_total = q.max_total;
if (q.hostels === '0') lq.include_hostels = 'false';
const latestQuery = Object.entries(lq).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&');

// ?live=1 o "cualquier día" => siempre búsqueda en vivo
const forceLive = q.live === '1' || q.weekdays === 'any';

return [{ json: { api: API, apiKey: API_KEY, body, form: q, latestQuery, forceLive } }];

const d = $input.first().json;
const pre = d.source === 'precomputed';
const ago = (m) => (m == null ? '—' : m < 60 ? `hace ${m} min` : `hace ${Math.round(m / 60)} h`);
let liveReason = [];
try { liveReason = pre ? [] : ($('Ofertas precalculadas').first().json.coverage_notes || []); } catch (e) {}
const form = $('Preparar petición').first().json.form || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const liveQs = Object.entries({ ...form, live: '1' }).filter(([, v]) => v !== undefined && v !== '').map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
const DIAS = ['lun', 'mar', 'mié', 'jue', 'vie', 'sáb', 'dom'];
const fecha = (iso) => { const t = new Date(iso + 'T12:00:00'); return `${DIAS[(t.getDay() + 6) % 7]} ${t.getDate()}/${t.getMonth() + 1}`; };
const hora = (s) => esc(String(s || '').split(' on ')[0]);

const css = `
:root{--bg:#f6f7f9;--card:#fff;--text:#1d2330;--muted:#6b7280;--line:#e5e7eb;--accent:#0b63ce;--good:#0f7b3f;--chip:#eef2f7}
@media (prefers-color-scheme:dark){:root{--bg:#111418;--card:#1a1f26;--text:#e7eaee;--muted:#9aa3ae;--line:#2a313a;--accent:#5aa2ff;--good:#4cc38a;--chip:#232a33}}
*{box-sizing:border-box}body{margin:0;font:15px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--text)}
main{max-width:980px;margin:0 auto;padding:20px 16px 40px}h1{font-size:22px;margin:0 0 4px}h2{font-size:16px;margin:28px 0 10px}
.sub{color:var(--muted);margin:0 0 16px}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px}
form{display:flex;flex-wrap:wrap;gap:10px;align-items:end}label{display:flex;flex-direction:column;font-size:12px;color:var(--muted);gap:3px}
input{font:inherit;padding:6px 8px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--text);width:120px}
button{font:inherit;padding:7px 14px;border:0;border-radius:6px;background:var(--accent);color:#fff;cursor:pointer}
.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.stat{flex:1 1 140px}.stat b{display:block;font-size:22px}.stat span{color:var(--muted);font-size:12px}
.tw{overflow-x:auto}table{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden}
th,td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;white-space:nowrap}th{font-size:12px;color:var(--muted);font-weight:600}
td.p{font-weight:700;color:var(--good);font-variant-numeric:tabular-nums}a{color:var(--accent)}
.chips{display:flex;flex-wrap:wrap;gap:6px}.chip{background:var(--chip);border-radius:999px;padding:3px 10px;font-size:13px}.chip.ok{outline:1px solid var(--good)}
.err{border-color:#d33;color:#d33}.muted{color:var(--muted)}`;

const f = (name, label, ph) => `<label>${label}<input name="${name}" value="${esc(form[name])}" placeholder="${ph}"></label>`;
const formHtml = `<div class="card"><form method="get">
${f('max_price', 'Precio máx. (€)', '100')}${f('weekdays', 'Días salida (0=lun…6=dom, any)', '4')}
${f('min_nights', 'Noches mín.', '2')}${f('max_nights', 'Noches máx.', '3')}
${f('date_from', 'Desde (AAAA-MM-DD)', '+7 días')}${f('date_to', 'Hasta', '+4 semanas')}
${f('destinations', 'Destinos (LON,ROM…)', 'todas')}${f('origin', 'Origen', 'AGP')}
<button>Buscar</button></form>
<p class="muted" style="margin:8px 0 0;font-size:12px">Salidas jue/vie/sáb de 2-4 noches en las próximas 8 semanas: al instante (precalculado). Fuera de eso se busca en vivo y tarda unos minutos.</p></div>`;

let content;
if (!d.job_id && !pre) {
  const det = Array.isArray(d.detail) ? d.detail.map((x) => (typeof x === 'string' ? x : x.msg)).join('<br>') : esc(d.detail || JSON.stringify(d));
  content = `<div class="card err" style="margin-top:14px"><b>La API rechazó la búsqueda</b><br>${det}</div>`;
} else {
  const r = d.request;
  const deals = d.deals || [];
  const rows = deals.map((x) => `<tr><td class="p">${x.price.toFixed(0)} €</td><td><b>${esc(x.city)}</b> <span class="muted">${esc(x.destination)}</span></td>
<td>${fecha(x.departure_date)} → ${fecha(x.return_date)}</td><td>${x.nights}</td><td>${esc(x.airline)}</td>
<td>${hora(x.departure)}–${hora(x.arrival)}</td><td>${esc(x.duration)}</td><td>${esc(x.stops_text)}</td>
<td><a href="${esc(x.google_flights_url)}" target="_blank" rel="noopener">Ver</a></td>
<td>${x.hotel ? `<a href="${esc(x.hotel.url || x.google_hotels_url)}" target="_blank" rel="noopener">${esc(x.hotel.name)}</a><br><span class="muted">${x.hotel.price_total.toFixed(0)} € · ${x.hotel.rating ?? '—'}★${x.hotel.hostel ? ' · albergue' : ''}</span>`
      : (x.google_hotels_url ? `<a href="${esc(x.google_hotels_url)}" target="_blank" rel="noopener" class="muted">Buscar</a>` : '—')}</td>
<td class="p">${x.trip_total != null ? x.trip_total.toFixed(0) + ' €' : '—'}</td></tr>`).join('');
  const chips = (d.cheapest_by_destination || []).map((x) => `<span class="chip ${x.is_deal ? 'ok' : ''}">${esc(x.city)} ${x.price.toFixed(0)} €</span>`).join('');
  const best = deals[0];
  content = `
<div class="stats">
<div class="card stat"><b>${d.deals_count}</b><span>ofertas ≤ ${r.max_price} €</span></div>
<div class="card stat"><b>${best ? best.price.toFixed(0) + ' €' : '—'}</b><span>${best ? esc(best.city) + ', ' + fecha(best.departure_date) : 'sin ofertas'}</span></div>
${pre ? `<div class="card stat"><b>${ago(d.age_minutes)}</b><span>actualizado (precálculo)</span></div>` : `<div class="card stat"><b>${d.progress.total}</b><span>consultas en vivo (${d.progress.errors} sin datos)</span></div>`}
</div>
${pre ? `<p class="muted">Resultados precalculados (se actualizan a diario). <a href="?${liveQs}">Buscar en vivo</a> · tarda unos minutos</p>` : (liveReason.length ? `<p class="muted">Búsqueda en vivo: ${esc(liveReason.join(' · '))}</p>` : '')}
<h2>Ofertas</h2>
${deals.length ? `<div class="tw"><table><thead><tr><th>Precio</th><th>Destino</th><th>Fechas</th><th>Noches</th><th>Aerolínea</th><th>Horario ida</th><th>Duración</th><th>Escalas</th><th>Vuelo</th><th>Alojamiento</th><th>Vuelo + aloj.</th></tr></thead><tbody>${rows}</tbody></table></div>`
    : `<div class="card">No hay vuelos por debajo de ${r.max_price} € con estos filtros. Mira abajo el más barato de cada destino.</div>`}
<h2>Lo más barato por destino</h2><div class="chips">${chips || '<span class="muted">Sin datos</span>'}</div>
${(d.no_results || []).length ? `<p class="muted">Sin resultados: ${esc(d.no_results.join(', '))}</p>` : ''}`;
}

const r = d.request || {};
const sub = (d.job_id || pre)
  ? `Desde ${esc(r.origin)} · salidas del ${esc(r.date_from)} al ${esc(r.date_to)} · ${r.min_nights}-${r.max_nights} noches${r.departure_weekdays ? ' · ' + r.departure_weekdays.map((n) => DIAS[n]).join(', ') : ''}`
  : 'Ida y vuelta a capitales europeas';

const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ofertas de vuelos</title><style>${css}</style></head><body><main>
<h1>✈️ Ofertas de vuelos</h1><p class="sub">${sub}</p>${formHtml}${content}
<p class="muted" style="margin-top:24px;font-size:12px">Precios ida y vuelta por persona según Google Flights · ${new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' })}</p>
</main></body></html>`;

return [{ json: { html } }];
